H.exBulkCopy=function(){var cards=pool();if(!cards.length){toast('Нет карточек');return}var lines=cards.map(function(c){return c.en+' | '+c.ru});var head='Дай по 3 коротких примера (5-8 слов) на английском для каждой фразы в разных контекстах. Формат ответа: фраза | пример. Одна строка = один пример. Без нумерации, без пояснений, свои примеры.\n\n';var txt=head+lines.join('\n');try{navigator.clipboard.writeText(txt)}catch(e){}var ta=document.createElement('textarea');ta.value=txt;ta.style.position='fixed';ta.style.left='-9999px';document.body.appendChild(ta);ta.select();try{document.execCommand('copy')}catch(e){}ta.remove();toast('Скопировано: '+cards.length+' фраз')};
H.exImport=function(){showInputModal('Вставьте ответ ИИ (фраза | пример)','','',function(txt){var added=0,skipped=0;var map={};S.cards.forEach(function(c){map[nz(c.en)]=c});String(txt||'').split(/\n+/).forEach(function(line){line=line.trim();if(!line||line.length<4)return;if(/^(---|===|##|вот|here|ниже|пример)/i.test(line))return;var parts=line.split('|').map(function(x){return x.trim()});if(parts.length<2)return;var key=nz(parts[0]),ex=parts[parts.length-1];if(!key||!ex)return;var c=map[key];if(!c){skipped++;return}c.exs=c.exs||[];if(c.exs.indexOf(ex)>=0){skipped++;return}c.exs.push(ex);if(!c.ex)c.ex=c.exs[0];added++});if(added){invalidateAll();save();switchTab(tab)}toast('Добавлено: '+added+', пропущено: '+skipped)})};
